
.public-calendar-subscription-picker {
	padding: calc(var(--default-grid-baseline) * 4);

	h2 {
		margin-top: 0;
	}

	&__attribution {
		color: var(--color-text-maxcontrast)
	}

	&__region {
		display: flex;
		margin-top: calc(var(--default-grid-baseline) * 6);
		align-items: center;

		&__name {
			flex-grow: 1;

			p {
				font-weight: bold;
			}

			&__subline {
				color: var(--color-text-maxcontrast)
			}
		}
	}
}
